-- ov3-teach-04-flight-plans.sql
--
-- ============================== PREFLIGHT - NOT AN INSTALL ==============================
-- Byte-identical to the .commit twin except this banner and the terminal statement:
-- ROLLBACK TRANSACTION here, COMMIT TRANSACTION there. Nothing is written.
--
-- WHAT THIS ADDS: revision 2 of three plans that ov3-teach-02 recorded and that were reviewed but never approved -
-- skills-1 and skills-2 (DSL routing lines corrected in spec-capability-declaration and spec-scenario-topology) and
-- project (task oewf-w1-dsl-route-progress added) - and revision 1 of the graph-topology-emission repair plan.
-- Expected plan_revision: 2, 2, 2, 1. The workflow plan from ov3-teach-02 is unchanged and is not re-recorded.
-- Each plan is the evidence.flight_plan row of its planner id, holding exactly the estate-flight-plan.v1 steps of the
-- reviewed ov3-teaching/flights/*.steps.candidate.json file. It runs the installed writer evidence.upsert_flight_plan
-- (the statement record-flight-plan runs). It approves nothing and flies nothing. Re-running is harmless: an
-- unchanged plan keeps its revision.
--
-- WHERE: the sfx-identity database. Run the whole file in one session; the transaction spans the batches.
--
-- GUARD: the writer exists with its four parameters, and the owner principal is active. Otherwise nothing runs.
--
-- RESULT SETS: guard; plans (one row per flight: planner id, promise, plan revision and digest; matches_reviewed_file
-- = 1 when the digest equals SHA-256 of objective + NUL + stepsJson of the reviewed file).
--
-- NEXT: tell OV3 to review each re-recorded plan; an earlier review names an earlier digest (ov3-teaching/README.md).
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;
DECLARE @params int=(SELECT COUNT(*) FROM sys.parameters WHERE object_id=OBJECT_ID(N'evidence.upsert_flight_plan') AND name IN (N'@principal_id',N'@agent_id',N'@objective',N'@steps_json'));
DECLARE @active int=(SELECT COUNT(*) FROM [identity].principal WHERE principal_id='565de6d4-ebcd-408b-9359-04d21dc62183' AND active=1);
SELECT N'guard' AS result_set,@params AS writer_parameters,4 AS expected_parameters,@active AS owner_principal_active;
IF @params<>4 OR @active<>1
BEGIN
 RAISERROR(N'OV3_TEACH_PLAN_GUARD: evidence.upsert_flight_plan or the owner principal is not as reviewed; nothing was recorded.',16,1);
 ROLLBACK TRANSACTION;
 SET NOEXEC ON;
END
GO
DECLARE @p uniqueidentifier='565de6d4-ebcd-408b-9359-04d21dc62183';
DECLARE @r TABLE(plan_revision bigint,plan_digest binary(32),updated_at datetime2(7));
DECLARE @plans TABLE(ordinal int IDENTITY(1,1),agent_id nvarchar(255),promise_id nvarchar(200),expected_hex varchar(66),plan_revision bigint,plan_digest binary(32),updated_at datetime2(7));
INSERT @r EXEC evidence.upsert_flight_plan @principal_id=@p,@agent_id=N'claude-code-opus-5-5-ov3-teaching-skills-1',@objective=N'Register the specification-pack skills spec-pack-intake and spec-capability-declaration (group 1 of 2) and read each revision back by content digest.',
 @steps_json=N'[{"stepId":"plan-header","contractId":"estate-flight-plan.v1","promiseId":"ov3-teach-spec-skills-1","flightType":"execution","workClass":"skill-registration","unknowns":[]},{"stepId":"file-spec-pack-intake","capabilityId":"apply-declared-change","historicalBasis":"every skill in sidefx:agents was registered with the agent-specialization-change skill member and this verification (examples/json-authoring/skill-graph-topology-emission.change.json); writer model.apply_agent_specialization_document sha256:6e694646 retains content through OPENJSON","input":{"contractId":"declared-change.v1","changeKind":"agent-specialization-change","payload":{"contractId":"agent-specialization-change.v1","skill":{"skillId":"spec-pack-intake","summary":"Turn a specification pack into estate work without building: retain it by digest, bind every term to an installed surface or an exact gap, and preflight a tracker project whose tasks name capabilities and pin skills.","content":"# Spec pack intake and estate binding\n\nUse this skill when the owner hands the network a specification pack (a specification, build profiles, Gherkin acceptance, fixtures, a candidate flight-plan envelope) and asks for it to be built. It turns the pack into estate work without building anything: the pack retained by digest, every term the pack uses bound to an installed surface or recorded as a gap, and a tracker project whose tasks name capabilities and pin skills. A pack is a candidate. It never establishes admission, installation or runtime behavior.\n\n## Required inputs\n\n- The pack files and their UTF-8 SHA-256 digests.\n- The owner principal id and the planner agent id.\n- The selected estate model (estateModelPk) and a catalog digest from the first declared read that returns one. Pin both. Pass expectedCatalogDigest where a read accepts it; STALE_CATALOG means re-pin and re-read, not retry.\n\n## Allowed actions\n\n- Declared reads: read-mcp-catalog, list-capabilities, read-declared-identities, read-declared-capability-document, read-declared-contracts, read-declared-port-bindings, read-declared-composition, read-scenario-authority, read-topology-conformance, read-live-scenario-circuit, read-capability-dsl-specification, read-agent-specializations, read-specialist-selection, read-project-tracker.\n- Retain the pack as the owner''s artifact through apply-declared-change with changeKind content-artifact-change, so later calls can take it by digest.\n- Preflight a project-tracking change (apply-declared-change, changeKind project-tracking). Plan approval (planApprovalDate) and completion approval are owner acts; never set them.\n\n## Binding procedure\n\n1. Read the live inventory before claiming anything is missing. A named surface that is not installed is a work item, never a blocker, and never a reason to invent one.\n2. Give every capability, command, table, procedure, schema field, mechanic, role and vocabulary term the pack names exactly one disposition:\n   - BOUND: an installed surface carries the same meaning. Cite its id, document or definition digest and the read run id.\n   - EQUIVALENT: an installed surface carries the meaning under another name. Cite it, state the correspondence, and use the installed name from then on.\n   - AUTHORITY_GAP: no installed surface carries the meaning. Record source pointers and a bounded extension proposal naming its owner: sfx-embody for meaning, sfx-dal for identity, sfx-platform for delivery, SDA only by an evidenced request that names no provider.\n   - NOT_DECLARED or NOT_VERIFIABLE: the estate holds no declaration, or no read can verify one. This is a valid answer. Never fill it from layout, naming, indegree, Gherkin prose, a product dependency or a model explanation.\n3. Record name collisions. A pack word can name a different installed concept. In this estate \"workflow\" also means a CAPABILITY_WORKFLOW declaration (sidefx:workflows) flown by start-workflow-run; a specification''s \"workflow\" usually means scenario progression. Qualify every use: \"scenario workflow\" or \"workflow capability\".\n4. Separate illustrative identifiers (example field names, mission envelopes, candidate capability ids) from installed ones. Adopt an illustrative name only after the owner accepts it in the binding map; reuse an installed equivalent first.\n5. Map the pack''s mission envelope onto the estate flight format: the estate-flight-plan.v1 header (stepId plan-header, promiseId, flightType, workClass, unknowns), the promise retained as flight-promise:<promiseId> with obligations, and steps with expectations. The pack''s own envelope is never submitted as is.\n\n## Project and task shape\n\n- One project per pack, assigned to the actor that will execute it, carrying the agent user story and acceptance criteria from the pack.\n- One task per work package or gate. Keep the pack''s sequencing as dependencyRefs, not prose. A later phase stays OPEN behind its gate task.\n- Every task carries requiredOutcome, capabilityRef as \"<performing capability> (performs); <verifying read> (verifies)\" or \"UNRESOLVED: <what is missing> (performs); <read> (verifies)\", dependencyRefs, assignedActor and skillRefs as <skillId>@<revision>.\n- Read every pinned skill revision back first; the project writer refuses unknown refs with PROJECT_TASK_SKILL_UNKNOWN.\n\n## Output\n\n- The retained pack digests.\n- The binding map: term, disposition, installed surface, digest, run id, source pointer.\n- The gap list with owner and proposed path, and any owner decisions the pack leaves open.\n- The project-tracking change, preflighted, ready for owner review.\n\n## Stop conditions\n\nStop and report if the estate model or catalog digest cannot be pinned, if a read the procedure needs fails, or if a binding can only be made by assumption. Inventory may continue with the failing area labelled NOT_VERIFIABLE. Do not create scratch SQL, probe files or local scripts; a missing declared read is the next task.\n\n## Completion\n\nThe owner can read the binding map and see, for every pack term, the installed surface it maps to or the exact gap. The project and its tasks are preflighted. Nothing has been installed, admitted or flown.\n","capabilities":["read-mcp-catalog","list-capabilities","read-declared-identities","read-declared-capability-document","read-declared-contracts","read-declared-port-bindings","read-declared-composition","read-scenario-authority","read-topology-conformance","read-live-scenario-circuit","read-capability-dsl-specification","read-agent-specializations","read-specialist-selection","read-project-tracker","apply-declared-change"]},"verificationCapabilityId":"read-agent-specializations","preflight":{"input":{"skillId":"spec-pack-intake"},"expected":{"status":"READ"}},"route":{"resolvedDisposition":"RETURNED"}}},"obligationIds":["O1"],"expect":{"path":"$.disposition","equals":"COMMITTED"}},{"stepId":"prove-spec-pack-intake","capabilityId":"read-agent-specializations","historicalBasis":"read-agent-specializations {skillId, skillRevision} returned content and contentDigest = base64 SHA-256 of the registered UTF-8 content (run a5411039, 2026-11-02, eec-generic-governed-repair r1, equal to the 2026-10-18 export); selector exercised 21 times on 2026-10-27 (runs ae75d2ed, 26879a91)","input":{"skillId":"spec-pack-intake","skillRevision":1},"obligationIds":["O2"],"expect":{"path":"$.skills[0].contentDigest","equals":"FAxRx/1maHcI/UXTIyLJLM//MOjdsure8DFca+bzIYY="}},{"stepId":"file-spec-capability-declaration","capabilityId":"apply-declared-change","historicalBasis":"every skill in sidefx:agents was registered with the agent-specialization-change skill member and this verification (examples/json-authoring/skill-graph-topology-emission.change.json); writer model.apply_agent_specialization_document sha256:6e694646 retains content through OPENJSON","input":{"contractId":"declared-change.v1","changeKind":"agent-specialization-change","payload":{"contractId":"agent-specialization-change.v1","skill":{"skillId":"spec-capability-declaration","summary":"Build each capability a bound specification calls for through the declared pipeline, providers first (EXISTS, COMPOSE, LEAF), entries as capabilities, DSL to compile to draft to planned build and first-call flights, repeatable builds as workflow capabilities.","content":"# Declare capabilities from a bound specification\n\nUse this skill for a tracker task that builds a capability a specification calls for. Build it through the declared pipeline, providers first, and prove it with a real first call. Meaning is authored in rows; no capability meaning, wiring, contract or transformation lives in local executable code. The binding map from spec-pack-intake comes first.\n\n## Required inputs\n\n- The task, its binding-map entries and its acceptance.\n- The capability''s identity: an installed equivalent when the binding map found one, otherwise the accepted candidate id (ids match ^[a-z0-9][a-z0-9.-]*$).\n- Its input and outcome contracts and its effects.\n\n## Providers first\n\n1. Decompose the capability into effects: what it reads and from where, what it writes, which external service it calls, what it decides or transforms, where it needs a model, and what it delivers.\n2. Resolve each effect against the estate with read-declared-port-bindings, analysis-read-provider-slot-bindings, analysis-read-slot-provider-candidates, search-provider-registry and read-provider-registry. Classify each:\n   - EXISTS: a provider capability serves the effect. Bind it and cite a prior successful binding.\n   - COMPOSE: no provider serves it, but existing leaves can. Build a new provider capability the same way, first.\n   - LEAF: no leaf family serves it. Write it first as the code it would be, then declare it as dependency programs the resolvers run. Only a gap in the generic resolver goes to SDA.\n3. Build leaves first. A provider passes its first call before the root binds it.\n4. Prefer our providers over SDA platform debt bindings when both serve an effect. Never design a new tree onto debt.\n\n## Entries\n\nEach independently invocable entry the specification names is its own capability. Its root scenario is reached through its CLI interface (<capabilityId>-cli, rootScenarioId). An external system is never an entry. It is a provider beneath an event (identity, data supply), or the input source of an estate-owned ingress capability that admits its signal. Never turn a provider id into a capability id to preserve a diagram.\n\n## Authoring path\n\n- Text is capability-dsl.v1, compiled by analysis.compile_capability_dsl. The installed compiler is ahead of read-capability-dsl-specification. It accepts capability, intent, outcome, inquiry (up to three), input contract, output contract, cli display, scenario [root] [terminal], given, when, then, operation kind invoke-port, bind or platform bind with platform, provider, statement, result or config, and provider binding. It also accepts the routing lines route, broadcast, join and recur (spec-scenario-topology). When the specification and the compiler disagree, read the compiler source (read-declared-object-source); the compiler decides.\n- compile-capability-dsl compiles the text or refuses with DSL_* diagnostics and line numbers. Fix the source, never the compiled document.\n- From a Markdown description: draft-capability-from-spec writes the DSL and the procedure it executes, compiles, preflights and stores the draft. Correct a draft by passing previousDraftArtifactId. plan-capability-flight then plans the build flight (install the procedure, read it back, declare from the draft DSL, read the declaration back) and, once declared, the first-call flight.\n- From finished DSL: follow flight-pattern-declare-capability-from-dsl (apply-declared-change capability-from-dsl, then read-declared-capability-document expecting the first operation id).\n- For a whole circuit at once, propose-capability-circuit returns a proposal (scenarios, providers, ports, Gherkin) for review. A proposal is not a declaration.\n- Engineering revisions follow the proven pattern only: read-declared-object-source for the base, draft-object-revision and retain it, apply-engineering-change mode preflight, then mode commit, then read back and invoke. A one-step author-plus-install is not an execution pattern.\n- Routes between the capability''s scenarios are DSL lines too: route, broadcast with join, and recur. What each means, and when a compiled route is admissible, is in spec-scenario-topology.\n\n## Making a build repeatable\n\nWhen the same staged sequence will run more than once (a baseline, a verification, an install by digest), declare it as a workflow capability: a CAPABILITY_WORKFLOW declaration in sidefx:workflows (objective, promiseId, workClass workflow-run, stages in the flight-step shape with {{principalId}}, {{runKey}}, {{agentId}}, {{parameters.<name>}}) plus a three-port capability document that dispatches start-workflow-run. Follow flight-pattern-declare-capability-from-dsl and flight-pattern-workflow-run. Limits: parameters and binds are scalars, a stage cannot fly another run, and the host stops a run at 300 s.\n\n## Do not\n\n- Hand-write INSERT, UPDATE or DELETE where an installed writer expresses the change.\n- Create scratch SQL, probe files or local scripts. A missing read or writer is the next task.\n- Name a specific capability, scenario, contract or provider in runtime code.\n- Reference legacy v_* views or functions not named fv_* in new declarations.\n- Label a fixture provider as a live external integration.\n\n## Evidence\n\nFor each capability, retain: the draft artifact id; compile status and document digest; procedure digests before and after; preflight and commit receipts; the read-declared-capability-document readback; read-declared-port-bindings for every port; the first-call run id and outcome; read-topology-conformance for the capability.\n\n## Stop conditions\n\nStop when a provider claim cannot be confirmed by a declared read (refuse it by name), when a contract can only be completed by guessing, or when a needed writer is missing (declare the writer first, as its own task).\n\n## Completion\n\nThe capability is declared, its providers are bound and pass their first calls, and its own first call returns the declared outcome on a real run. The readbacks show exactly what the draft declared.\n","capabilities":["read-capability-dsl-specification","compile-capability-dsl","draft-capability-from-spec","plan-capability-flight","propose-capability-circuit","draft-object-revision","apply-engineering-change","apply-declared-change","read-declared-capability-document","read-declared-port-bindings","analysis-read-provider-slot-bindings","analysis-read-slot-provider-candidates","search-provider-registry","read-provider-registry","read-topology-conformance","model-declare-semantic-object","start-workflow-run"]},"verificationCapabilityId":"read-agent-specializations","preflight":{"input":{"skillId":"spec-capability-declaration"},"expected":{"status":"READ"}},"route":{"resolvedDisposition":"RETURNED"}}},"obligationIds":["O1"],"expect":{"path":"$.disposition","equals":"COMMITTED"}},{"stepId":"prove-spec-capability-declaration","capabilityId":"read-agent-specializations","historicalBasis":"read-agent-specializations {skillId, skillRevision} returned content and contentDigest = base64 SHA-256 of the registered UTF-8 content (run a5411039, 2026-11-02, eec-generic-governed-repair r1, equal to the 2026-10-18 export); selector exercised 21 times on 2026-10-27 (runs ae75d2ed, 26879a91)","input":{"skillId":"spec-capability-declaration","skillRevision":1},"obligationIds":["O2"],"expect":{"path":"$.skills[0].contentDigest","equals":"QrY+RzW6UrwNGIyjZ5iLt021MQogGkkyehWhawWBEJ8="}}]';
INSERT @plans(agent_id,promise_id,expected_hex,plan_revision,plan_digest,updated_at) SELECT N'claude-code-opus-5-5-ov3-teaching-skills-1',N'ov3-teach-spec-skills-1','0x4821b1e1c0a430f774535eef7e5e7471df2e1467aa800448e0acd78b39081bbc',plan_revision,plan_digest,updated_at FROM @r;
DELETE @r;
INSERT @r EXEC evidence.upsert_flight_plan @principal_id=@p,@agent_id=N'claude-code-opus-5-5-ov3-teaching-skills-2',@objective=N'Register the specification-pack skills spec-scenario-topology and spec-acceptance-and-closure (group 2 of 2) and read each revision back by content digest.',
 @steps_json=N'[{"stepId":"plan-header","contractId":"estate-flight-plan.v1","promiseId":"ov3-teach-spec-skills-2","flightType":"execution","workClass":"skill-registration","unknowns":[]},{"stepId":"file-spec-scenario-topology","capabilityId":"apply-declared-change","historicalBasis":"every skill in sidefx:agents was registered with the agent-specialization-change skill member and this verification (examples/json-authoring/skill-graph-topology-emission.change.json); writer model.apply_agent_specialization_document sha256:6e694646 retains content through OPENJSON","input":{"contractId":"declared-change.v1","changeKind":"agent-specialization-change","payload":{"contractId":"agent-specialization-change.v1","skill":{"skillId":"spec-scenario-topology","summary":"Declare a specification''s scenario workflows on exact estate carriers (routing topologyKind and semanticProgress, executionGraph groups), keep provider, composition, product and navigation relations out of routes, fail closed, and reveal them as a read-only lens.","content":"# Declare and reveal scenario workflows faithfully\n\nUse this skill when a specification describes workflows as scenario progression: entries, routes, branches, fan-out, convergence, returns and terminals. Declare each route on an exact estate carrier or hold it as a finding. Keep provider bindings, capability composition, product dependencies and navigation out of execution routes. (A workflow capability in sidefx:workflows is a different object; see spec-capability-declaration.)\n\n## Laws\n\n- A scenario workflow is what is reachable from one declared entry by following only declared, admitted scenario routes. Reachability across any other relation is not execution.\n- Zero inbound edges is neither necessary nor sufficient for entry status. Entries come from declared entry authority, never from indegree, top placement, naming, a UI link or an HTTP endpoint alone. A scenario with inbound routes can still be an independent entry.\n- Fail closed. A route with missing topology, missing semanticProgress, an unknown selecting variant, an unresolved identity or unsupported cross-altitude meaning is not traversed. It is a finding with a source pointer, never a best-guess arrow.\n- One semantic identity per scenario. A scenario reached from two entries is referenced, never cloned.\n- Preserve every admitted terminal disposition. Do not invent a single success terminal.\n\n## Vocabulary map\n\nThe specification''s terms are the canonical-circuit-blueprint.v1 vocabulary (ADR-001). The estate declares routes at $.semantics.routing of a capability envelope (members fromScenario, variant, toScenario, topologyKind, groupId, joinSlotId, semanticProgress) and concurrency at $.semantics.executionGraph. Routes are authored as DSL lines. Re-read the installed sources before relying on a row of this map.\n\n| Blueprint term | DSL line | Estate topologyKind | Estate semanticProgress | Notes |\n| --- | --- | --- | --- | --- |\n| TRANSITION | route <from> <variant> to <to> | selection; sequence or return when hand-minted | narrowing, or terminating at a terminal target; preserving | progression inside one capability |\n| BRANCH_ROUTE | one route line per variant | selection | narrowing; terminating at a terminal target | exclusive; endpoint contracts must agree (EDGE_CONTRACT_MISMATCH) |\n| FAN_OUT_MEMBER | broadcast <root> to <leg>,<leg> | broadcast (enter-<leg>) | expanding | a broadcast without a join refuses; edgeGroup policy all with a dispatchAuthority |\n| CONVERGENCE_REQUIREMENT | join <scenario> from <leg>,<leg> | join (settle-<leg>) and failure (fail-<leg>) | converging | one joinSlotId per leg; the leg sets must agree |\n| BOUNDED_RETURN | recur <scenario> while <continue> until <stop> max <n> | recurrence | recurring | always write max: without it the bound is 2147483647, so treat it as unbounded and hold it |\n| ALTITUDE_DESCENT | none (not a route) | none | none | scenario operation, port, port binding, provider slot, provider |\n| none (estate only) | from join | failure | converging with joinSlotId, otherwise terminating | branchFailure collect |\n| none (estate only) | none | cancellation | terminating | |\n\nKnown gaps:\n- The compiler writes semanticProgress only for recur. Route, broadcast and join transitions compile without it, and neither model.declare_capability_topology nor model.declare_capability_envelope adds it.\n- Blueprint progress ESTABLISHES and DESCENDS have no estate value.\n- read-capability-dsl-specification lists none of route, broadcast, join, recur or inquiry. The compiler is the authority.\n\n## Relations that are never routes\n\n- Provider binding: a scenario port bound to a provider (DSL bind or platform bind, provider slots, read-declared-port-bindings). Show it only under descent.\n- Capability composition: an operation that invokes another capability (nested invocation through ScenarioKernel.NodePlatform; read-declared-composition). This is descent into a shared responsibility. It can be how one workflow submits to another capability''s responsibility, but it is labelled composition, not a route.\n- Product dependency: one capability''s outcome satisfying another''s input. It makes a product available; it never invokes the consumer. No estate carrier for it is verified. Until one is, show it only as a labelled overlay derived from shared contract identities (read-declared-contracts), or report NOT_DECLARED.\n- UI navigation, catalog lookup, actor relationships, provider testimony and any unknown edge.\n\n## Declaring\n\n1. Entries: one capability per independently invocable entry (spec-capability-declaration). An external signal enters through an estate-owned ingress capability that admits it.\n2. Routes inside a capability are DSL lines in its source. capability-from-dsl compiles them into $.semantics.routing and $.semantics.executionGraph, and model.declare_capability_topology writes them through model.declare_capability_envelope, the only writer for routing. The compiler enforces these rules: every route endpoint and variant resolves inside the document; a broadcast needs a join over the same legs; a recurring scenario declares both variants, and its outcome contract equals its input contract. Hand re-minting an envelope (graph-topology-emission) is only for topology the DSL cannot express. Re-mint; never patch.\n3. Every route carries semanticProgress. A compiled route, broadcast or join transition lacks it until the compiler derives it. Report such a route as held, with that finding; never draw it. The derivation law is the one declared by declare-route-semantic-progress: selection narrowing, or terminating at a terminal target; broadcast expanding; join converging; failure converging with a join slot.\n4. Routes across capabilities: there is no cross-capability route carrier. Present the owner with the two options and their consequences: composition (the caller''s port bound to the callee capability; nested-capability-invocation), or one capability holding the shared scenarios. Record the decision in the binding map. Never decide silently.\n\n## Verifying\n\n- read-topology-conformance: violation pages, count-paired, with the catalog digest.\n- read-scenario-terminal-coverage: covered and missing outcome variants and contracts.\n- read-declared-composition: composition edges, kept apart from routes.\n- read-declared-port-bindings: the descent beneath each event.\n- read-live-scenario-circuit: the projected circuit and drill-down. Layout may vary between projections; membership and edge classes may not.\n- For concurrency, the overlap witness on real runs.\n\n## Revealing\n\nA workflow lens is read-only and changes nothing it reads. From one pinned snapshot it returns: entries with status (admitted, candidate, held); per-entry route closure; routes, composition edges, provider bindings and product overlays as separate lists; and findings. Every rendered edge carries its semantic id, topologyKind, semanticProgress, variant, source capability and definition digest. A held route holds only itself and what depends on it; independent workflows still render.\n\n## Stop conditions\n\nStop at a route whose carrier is missing. Record AUTHORITY_GAP with source pointers and continue with independent routes. Stop if a declaration would need an invented schema key; that is an extension proposal for owner review.\n\n## Completion\n\nEvery edge in the lens maps one to one to a declared routing entry or a composition edge, with its identity and digest. No execution arrow comes from a provider, product or navigation relation. Held routes are listed with their findings.\n","capabilities":["read-topology-conformance","read-scenario-terminal-coverage","read-declared-composition","read-declared-port-bindings","read-declared-contracts","read-live-scenario-circuit","read-scenario-authority","read-declared-capability-document","analysis-read-provider-slot-bindings"]},"verificationCapabilityId":"read-agent-specializations","preflight":{"input":{"skillId":"spec-scenario-topology"},"expected":{"status":"READ"}},"route":{"resolvedDisposition":"RETURNED"}}},"obligationIds":["O1"],"expect":{"path":"$.disposition","equals":"COMMITTED"}},{"stepId":"prove-spec-scenario-topology","capabilityId":"read-agent-specializations","historicalBasis":"read-agent-specializations {skillId, skillRevision} returned content and contentDigest = base64 SHA-256 of the registered UTF-8 content (run a5411039, 2026-11-02, eec-generic-governed-repair r1, equal to the 2026-10-18 export); selector exercised 21 times on 2026-10-27 (runs ae75d2ed, 26879a91)","input":{"skillId":"spec-scenario-topology","skillRevision":1},"obligationIds":["O2"],"expect":{"path":"$.skills[0].contentDigest","equals":"NFXVmmIT1v9usjHr30rZ1gRZXpevo3aNfeRdaOX5cV8="}},{"stepId":"file-spec-acceptance-and-closure","capabilityId":"apply-declared-change","historicalBasis":"every skill in sidefx:agents was registered with the agent-specialization-change skill member and this verification (examples/json-authoring/skill-graph-topology-emission.change.json); writer model.apply_agent_specialization_document sha256:6e694646 retains content through OPENJSON","input":{"contractId":"declared-change.v1","changeKind":"agent-specialization-change","payload":{"contractId":"agent-specialization-change.v1","skill":{"skillId":"spec-acceptance-and-closure","summary":"Turn a specification''s Gherkin and fixtures into reviewed flights with checkable expectations and historical basis, run negatives RED first, observe only real runs, and close on PROMISE_CLOSED with the six claims kept separate.","content":"# Specification acceptance as flights, and honest closure\n\nUse this skill to turn a specification''s Gherkin acceptance and fixtures into reviewed flights, and to close its promise only on evidence. Fixture expectations are hypotheses; only retained runs are evidence. The flight mechanics are in flight-pattern-promise-plan-review-report-approve, flight-pattern-workflow-run and flight-pattern-verification-publish-and-acceptance. This skill adds the rules a specification brings.\n\n## Required inputs\n\n- The bound acceptance scenarios and fixtures, retained by digest.\n- The capabilities under test, declared and read back.\n- The promise and its obligations, the owner principal id and the planner agent id.\n\n## From Gherkin to steps\n\n- stepsJson is an array. Element 0 is the estate-flight-plan.v1 header: stepId plan-header, promiseId, flightType (execution or discovery), workClass, unknowns. Each later element is a step: stepId, capabilityId, input matching the capability''s root input contract, obligationIds, expect {path, equals}, historicalBasis.\n- Each Gherkin scenario becomes one or more steps with a checkable expectation. The Then clause becomes expect, never prose. A Then that no result member can express is a gap in the capability''s outcome contract, not a reason to drop the check.\n- Every execution step names its historical basis: the prior successful retained execution or pattern that makes it admissible. A step without one belongs in a discovery flight, never an execution flight.\n- Negative fixtures run first and must be RED on the existing surface before any repair. An intentionally invalid specimen must be rejected by a real run; if no surface can consume the specimen at all, that absence is the finding. A green negative is a defect in the test, not a pass.\n- An expected-defect baseline is accepted as a baseline while its conformance finding stays FAIL. After-state PASS alone does not close a task; it needs the accepted baseline and a transition comparison.\n\n## The process\n\nThe planner retains the promise, records the plan (record-flight-plan, or start-workflow-run for a workflow capability), and has it reviewed (review-flight-plan; fix PLAN_*, STEP_* and PROMISE_* findings by re-planning). The report comes from generate-flight-plan-report-md. The owner approves, and the planner records the approval at once with approve-flight-plan, quoting the owner. resolve-flight-clearance clears it. The owner triggers it through OV3, and OV3 flies it. The planner never triggers on its own initiative. The reviewer and the reporter never approve or fly.\n\n## Observation\n\n- A flight begins its recording before the first executable step and completes it on every terminal disposition. A run with no flight recording informs the next plan but cannot establish acceptance.\n- Execution testimony comes from real runs: read-run-cell-testimony, read-flight-recording, read-flight-progress, and sfx-api run <runId>. A fixture value never renders as EXECUTED; without a receipt it is NOT_OBSERVED.\n- Provider swaps, concurrency, authorization refusals and held-route cases are proven by real signals, not screenshots or replays.\n- Never resubmit an unknown outcome automatically. Reconcile it by run id.\n\n## Closure and the final report\n\n- read-flight-closure must return PROMISE_CLOSED. A green step is not a closed promise.\n- Record task evidence through project-tracking (apply-declared-change, or coordinate-project-task RECORD) with task-execution-evidence.v1 references. A task is DONE only when its acceptance is demonstrated.\n- The mission disposition is COMPLETE, PARTIAL_WITH_HELD_GAPS or NOT_ADMITTED. Keep six claims separate: specification written, fixture valid, graph projected, provider invoked, workflow executed, promised outcome evidenced.\n- The final report gives: the snapshot identity and digests; admitted entries with their rationale and source pointers; routes, composition edges, provider bindings and product overlays as separate inventories from the same snapshot; expected versus observed fixture dispositions, negatives included; parity across the projection targets actually admitted; held gaps with owners; and receipts only where the lifecycle produced them. No invented digest appears anywhere.\n\n## Stop conditions\n\nStop if a step''s capability or input does not resolve (STEP_CAPABILITY_UNKNOWN, STEP_INPUT_CONTRACT_MISMATCH), if an obligation has no checkable expectation (PROMISE_OBLIGATION_UNCOVERED), or if closure is asked for without a recording.\n\n## Completion\n\nEvery acceptance scenario is a reviewed step with a real-run result. Negatives were RED before repair. Closure reads PROMISE_CLOSED. The report keeps the six claims separate and names every held gap.\n","capabilities":["record-flight-plan","read-flight-plan","review-flight-plan","generate-flight-plan-report-md","approve-flight-plan","resolve-flight-clearance","fly-flight-plan","read-flight-progress","read-flight-recording","read-flight-closure","read-run-cell-testimony","start-workflow-run","publish-workflow-verification","coordinate-project-task","apply-declared-change"]},"verificationCapabilityId":"read-agent-specializations","preflight":{"input":{"skillId":"spec-acceptance-and-closure"},"expected":{"status":"READ"}},"route":{"resolvedDisposition":"RETURNED"}}},"obligationIds":["O1"],"expect":{"path":"$.disposition","equals":"COMMITTED"}},{"stepId":"prove-spec-acceptance-and-closure","capabilityId":"read-agent-specializations","historicalBasis":"read-agent-specializations {skillId, skillRevision} returned content and contentDigest = base64 SHA-256 of the registered UTF-8 content (run a5411039, 2026-11-02, eec-generic-governed-repair r1, equal to the 2026-10-18 export); selector exercised 21 times on 2026-10-27 (runs ae75d2ed, 26879a91)","input":{"skillId":"spec-acceptance-and-closure","skillRevision":1},"obligationIds":["O2"],"expect":{"path":"$.skills[0].contentDigest","equals":"1AMpeJPKFIIB/hCUbPq9qzdfpu/AcSNsbTLi/zjl8nk="}}]';
