INSERT @r EXEC evidence.upsert_flight_plan @principal_id=@p,@agent_id=N'claude-code-opus-5-5-ov3-teaching-gte',@objective=N'Re-register skill graph-topology-emission as revision 2 with its original content and read it back by content digest.',
 @steps_json=N'[{"stepId":"plan-header","contractId":"estate-flight-plan.v1","promiseId":"ov3-teach-gte-r2","flightType":"execution","workClass":"skill-registration","unknowns":[]},{"stepId":"file-graph-topology-emission-r2","capabilityId":"apply-declared-change","historicalBasis":"the skill member with baseRevision took objective-request-construction to revision 2 (examples/json-authoring/skill-objective-request-construction-rev2.change.json; it reads revision 3 today); writer model.apply_agent_specialization_document sha256:6e694646 refuses a stale base (AGENT_SKILL_STALE_BASE) and retains content through OPENJSON (run f71bcd63)","input":{"contractId":"declared-change.v1","changeKind":"agent-specialization-change","payload":{"contractId":"agent-specialization-change.v1","skill":{"skillId":"graph-topology-emission","summary":"Declared concurrent topology and its witness","content":"# Emit and witness declared concurrent topology\n\nConcurrency in the estate is declared data: a capability''s envelope carries an\n`executionGraph`, `analysis.capability_graph_source` copies six keys onto the\ngraph source, and the kernel compiler turns them into a plan. One scenario\nwith sequential operations compiles to `edge:sequence`; independent branches\nexist only when the declaration says so.\n\n## 1. The envelope shape (proven, four-branch circuit)\n\n`$.semantics.executionGraph`:\n\n```json\n{ \"graphType\": \"sda-semantic-execution-graph.v2\",\n  \"requiredExecutionFeatures\": [\"declared-concurrent-dispatch.v1\"],\n  \"readyArbitration\": \"causal-activation-order.v1\",\n  \"executionBudget\": { \"maximumInFlightEffects\": N, \"deadlineMs\": 60000 },\n  \"dispatchAuthorities\": [ { \"dispatchAuthorityId\": \"circuit-dispatch.v1\",\n    \"mode\": \"concurrent\", \"legCount\": N, \"maximumActiveBranches\": N,\n    \"maximumInFlightEffects\": N, \"readyOrder\": \"declared-edge-order\",\n    \"branchFailure\": \"collect\", \"ownership\": \"join-before-return\" } ],\n  \"edgeGroups\": [\n    { \"groupId\": \"circuit-fan\", \"kind\": \"broadcast\", \"policy\": \"all\",\n      \"edgeIds\": [\"edge:enter-<leg>\", ...],\n      \"dispatchAuthorityId\": \"circuit-dispatch.v1\",\n      \"completionJoinGroupId\": \"circuit-converge\" },\n    { \"groupId\": \"circuit-converge\", \"kind\": \"join\", \"policy\": \"all-required\",\n      \"edgeIds\": [\"edge:settle-<leg>\", ...],\n      \"joinCellId\": \"cell:scenario:<assessment-scenario>\",\n      \"requiredSlotIds\": [\"<leg>\", ...] } ] }\n```\n\nRouting transitions (`$.semantics.routing`, consumed by\n`analysis.capability_declared_transitions`) carry `topologyKind`\n(`broadcast` | `join` | `failure` | `sequence`), `groupId` and `joinSlotId`.\nRule of thumb: three transitions per leg - `enter-<leg>` (broadcast),\n`settle-<leg>` (join, named slot), `fail-<leg>` (failure, same slot).\n\n## 2. Re-mint, don''t patch\n\nThe envelope is content-addressed. Change it by loading the current envelope,\n`JSON_MODIFY`-ing `$.semantics.cli|routing|executionGraph`, minting the new\ndefinition and capability version (the pattern in\n`complete-financial-branch-fanout.sql`), then re-declaring unchanged scenarios.\nProbe the graph source afterwards: graphType v2, `mode` concurrent,\n`maximumActiveBranches` N, transitions = 3N, fan edges N, join slots N.\n\n## 3. The serial/concurrent distinction\n\n- Serial: no `executionGraph` on the envelope; events show `edge:sequence`\n  between all cells with disjoint `[startedAt, completedAt]` windows.\n- Concurrent: branch cells'' windows **overlap** (both start before either\n  completes - the slow branch is the barrier) and the join cell starts after\n  all required settlements.\n- The demo rig: `demo/dispatch-pair/` (`fixture-server.mjs` provides the 400ms\n  barrier; `observation-capture.v1.txt` documents the capture shape).\n  `dispatch-pair-demo` switches M1 serial / M2 concurrent by re-minting one\n  declared value; input contract requires `{contractId, payload:{symbol}}` when\n  the catalog is healthy.\n- Witness discipline: retain both runs; read the timelines (events or the\n  rig''s capture); assert overlap programmatically. A missing or empty events\n  page is not proof of absence - read the run output contract as well.\n\n## 4. The admission/catalog dependency\n\nLive invocation refuses `CAPABILITY_INPUT_JSON_REJECTED` when the catalog''s\ncontract schema diverges from the caller''s input. The catalog resolves through\nscenario contract version pins; repairs follow the `derived-surface-repair`\nskill (scaffold residue and pin staleness are the usual causes).\n\n## 5. The DSL emission target\n\n`analysis.compile_capability_dsl` compiles the line-oriented DSL into the\ncapability document. The emission unit (`dsl-fanout-construct`) adds a\nconstruct for fan-out/dependency + join that emits `edgeGroups`,\n`dispatchAuthorities` and the routing transitions above, so the lane authors\nconcurrent topology from text (`sfx capability author --dsl`). Read the\ncompiler''s construct mechanics first and size the unit before promising it -\nconstructs may be table-driven or hardcoded. Keep serial and\ndependency-ordered (`sequence`) paths expressible; add a conformance vector.\n","baseRevision":1},"verificationCapabilityId":"read-agent-specializations","preflight":{"input":{"skillId":"graph-topology-emission"},"expected":{"status":"READ"}},"route":{"resolvedDisposition":"RETURNED"}}},"obligationIds":["O1"],"expect":{"path":"$.disposition","equals":"COMMITTED"}},{"stepId":"prove-graph-topology-emission-r2","capabilityId":"read-agent-specializations","historicalBasis":"read-agent-specializations {skillId, skillRevision} returned content and contentDigest = base64 SHA-256 of the registered UTF-8 content (run a5411039, 2026-11-02, eec-generic-governed-repair r1, equal to the 2026-10-18 export); selector exercised 21 times on 2026-10-27 (runs ae75d2ed, 26879a91)","input":{"skillId":"graph-topology-emission","skillRevision":2},"obligationIds":["O2"],"expect":{"path":"$.skills[0].contentDigest","equals":"9jShlYhjE5xL6oLSn9V8byIH77RyrvSyb2Aou9UqKKk="}}]';
INSERT @plans(agent_id,promise_id,expected_hex,plan_revision,plan_digest,updated_at) SELECT N'claude-code-opus-5-5-ov3-teaching-gte',N'ov3-teach-gte-r2','0xee94396c52cfe29e21d2057582e4486e856197be3b3e36e31f61b69a683deef3',plan_revision,plan_digest,updated_at FROM @r;
DELETE @r;
SELECT N'plans' AS result_set,ordinal,agent_id,promise_id,plan_revision,N'sha256:'+LOWER(CONVERT(varchar(64),plan_digest,2)) AS plan_digest,
 CASE WHEN plan_digest=CONVERT(binary(32),expected_hex,1) THEN 1 ELSE 0 END AS matches_reviewed_file,updated_at FROM @plans ORDER BY ordinal;
ROLLBACK TRANSACTION;
GO
SET NOEXEC OFF;
